package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*;
class MembershipSliceTest { @Test void membershipSubscriptionRenewsExistingMembership() throws Exception {Path p=Files.createTempFile("membership-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("m","password1");var u=us.authenticate("m","password1");var o=new OperationsService(db);long id=o.subscribeOrRenew(u.id(),"GOLD",30,5000);assertTrue(id>0);String first=o.membership(u.id());long renewed=o.subscribeOrRenew(u.id(),"GOLD",30,5000);assertEquals(id,renewed);assertNotEquals(first,o.membership(u.id()));}finally{Files.deleteIfExists(p);}}}
